"use strict";

// Only the Markdown constructs generated by Pulse. Never accept source HTML.
(function (root) {
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  function inline(text) {
    const tokens = /`[^`]+`|\*\*[^*]+\*\*|_[^_\n]+_|\[\d+\]|https?:\/\/[^\s<>]+/g;
    let html = "", last = 0;
    for (const match of text.matchAll(tokens)) {
      html += esc(text.slice(last, match.index));
      const token = match[0];
      if (token.startsWith("`")) html += `<code>${esc(token.slice(1, -1))}</code>`;
      else if (token.startsWith("**")) html += `<strong>${esc(token.slice(2, -2))}</strong>`;
      else if (token.startsWith("_")) html += `<em>${esc(token.slice(1, -1))}</em>`;
      else if (/^\[\d+\]$/.test(token)) {
        const n = token.slice(1, -1);
        html += `<a class="brief-citation" href="#brief-source-${n}" aria-label="Source ${n}">${esc(token)}</a>`;
      } else {
        try {
          const url = new URL(token);
          html += ["https:", "http:"].includes(url.protocol)
            ? `<a href="${esc(token)}" target="_blank" rel="noopener noreferrer">${esc(token)}</a>` : esc(token);
        } catch { html += esc(token); }
      }
      last = match.index + token.length;
    }
    return html + esc(text.slice(last));
  }
  root.renderBriefing = function (markdown) {
    const lines = String(markdown || "").replace(/\r/g, "").split("\n"), out = [];
    const cells = (line) => line.trim().replace(/^\||\|$/g, "").split("|").map((s) => s.trim());
    let sources = false;
    for (let i = 0; i < lines.length;) {
      const line = lines[i].trim();
      if (!line) { i++; continue; }
      const heading = line.match(/^(#{1,3})\s+(.+)$/);
      if (heading) {
        sources = heading[2] === "Sources";
        const n = Math.min(heading[1].length + 1, 4);
        out.push(`<h${n}>${inline(heading[2])}</h${n}>`); i++; continue;
      }
      if (line.startsWith("|") && /^\|?[\s:|-]+\|?$/.test(lines[i + 1]?.trim() || "")) {
        const headers = cells(line), rows = []; i += 2;
        while (i < lines.length && lines[i].trim().startsWith("|")) rows.push(`<tr>${cells(lines[i++]).map((c) => `<td>${inline(c)}</td>`).join("")}</tr>`);
        out.push(`<div class="brief-table" role="region" aria-label="Briefing table" tabindex="0"><table><thead><tr>${headers.map((c) => `<th scope="col">${inline(c)}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`); continue;
      }
      if (/^(?:- |\d+\. )/.test(line)) {
        const ordered = /^\d+\. /.test(line), pattern = ordered ? /^(\d+)\. (.*)$/ : /^- (.*)$/, items = [];
        while (i < lines.length && pattern.test(lines[i].trim())) {
          const item = lines[i++].trim().match(pattern);
          const id = sources && ordered ? ` id="brief-source-${item[1]}" tabindex="-1"` : "";
          items.push(`<li${id}>${inline(item[ordered ? 2 : 1])}</li>`);
        }
        const tag = ordered ? "ol" : "ul";
        out.push(`<${tag}>${items.join("")}</${tag}>`); continue;
      }
      const paragraph = [line]; i++;
      while (i < lines.length && lines[i].trim() && !/^(?:#|\||- |\d+\. )/.test(lines[i].trim())) paragraph.push(lines[i++].trim());
      out.push(`<p>${inline(paragraph.join(" "))}</p>`);
    }
    return out.join("\n");
  };
})(typeof window === "undefined" ? globalThis : window);
